INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist SLAAC die einzige Methode zur IPv6-Autokonfiguration?', 2, '[{"text": "Nein", "correct": true, "because": "DHCPv6 ist Alternative"}, {"text": "Ja", "correct": false, "because": "Mehrere Optionen existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt NDP bei SLAAC?', 3, '[{"text": "Liefert Router-Informationen", "correct": true, "because": "Router Advertisement"}, {"text": "Verschlüsselt Adressen", "correct": false, "because": "Keine Sicherheitsfunktion"}, {"text": "Weist Bandbreite zu", "correct": false, "because": "Netzwerkabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind bei SLAAC wichtig?', 5, '[{"text": "Router Advertisement", "correct": true, "because": "Enthält Präfix"}, {"text": "Neighbor Solicitation", "correct": true, "because": "Prüft Duplikate"}, {"text": "DNS-Server-Adresse", "correct": false, "because": "Separat konfiguriert"}, {"text": "HTTP-Anfrage", "correct": false, "because": "Andere Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SLAAC nutzt NDP. b) Es benötigt DHCPv6.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DHCPv6 ist optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der SLAAC-Analyse?', 4, '[{"text": "Router Advertisement", "correct": false, "because": "Kern der Konfiguration"}, {"text": "Duplicate Address Detection", "correct": false, "because": "Prüft Konflikte"}, {"text": "Webserver-Status", "correct": true, "because": "Nicht Netzwerk-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob SLAAC eine MAC-Adresse braucht?', 2, '[{"text": "Ja", "correct": true, "because": "Für Interface-ID"}, {"text": "Nein", "correct": false, "because": "Basis der Adressbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher NDP-Fehler verhindert SLAAC?', 3, '[{"text": "Fehlendes Router Advertisement", "correct": true, "because": "Kein Präfix verfügbar"}, {"text": "Echo Reply Ausfall", "correct": false, "because": "Ping-spezifisch"}, {"text": "DNS-Fehler", "correct": false, "because": "Nicht SLAAC-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Fehler können bei SLAAC auftreten?', 5, '[{"text": "Duplizierte Adresse", "correct": true, "because": "DAD schlägt fehl"}, {"text": "Kein Router Advertisement", "correct": true, "because": "Präfix fehlt"}, {"text": "Hohe Latenz", "correct": false, "because": "Diagnoseproblem"}, {"text": "Portblockade", "correct": false, "because": "Transportebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) SLAAC nutzt Multicast. b) Es funktioniert ohne Router. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Router für Präfix nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für SLAAC?', 4, '[{"text": "Router Advertisement", "correct": false, "because": "Liefert Präfix"}, {"text": "Interface-ID", "correct": false, "because": "Teil der Adresse"}, {"text": "DHCP-Server", "correct": true, "because": "SLAAC ist autonom"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist SLAAC immer erfolgreich?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von NDP"}, {"text": "Ja", "correct": false, "because": "Fehler möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Prozess prüft Adresskonflikte bei SLAAC?', 4, '[{"text": "Duplicate Address Detection", "correct": true, "because": "NDP-Mechanismus"}, {"text": "Router Solicitation", "correct": false, "because": "Fragt nur Präfix"}, {"text": "Echo Request", "correct": false, "because": "Ping-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass SLAAC ohne NDP funktioniert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "NDP ist essenziell"}, {"text": "Ja", "correct": false, "because": "Missverständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der SLAAC-Analyse?', 3, '[{"text": "Router Advertisement", "correct": true, "because": "Liefert Präfix"}, {"text": "Bandbreitenlimit", "correct": false, "because": "Nicht relevant"}, {"text": "DNS-Konfiguration", "correct": false, "because": "Separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) NDP-Fehler blockieren SLAAC. b) SLAAC ist DHCPv6-abhängig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SLAAC ist autonom"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet SLAAC?', 5, '[{"text": "Automatische Adresszuweisung", "correct": true, "because": "Ohne Server"}, {"text": "Konfliktvermeidung", "correct": true, "because": "Via DAD"}, {"text": "Hohe Sicherheit", "correct": false, "because": "Keine Verschlüsselung"}, {"text": "Geringe Latenz", "correct": false, "because": "Netzwerkabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der SLAAC-Analyse unwichtig?', 3, '[{"text": "Neighbor Solicitation", "correct": false, "because": "Prüft Duplikate"}, {"text": "Router Advertisement", "correct": false, "because": "Liefert Präfix"}, {"text": "Web-UI", "correct": true, "because": "Nicht Netzwerk-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann SLAAC ohne Router Advertisement laufen?', 3, '[{"text": "Nein", "correct": true, "because": "Präfix wird benötigt"}, {"text": "Ja", "correct": false, "because": "Router ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob SLAAC globale Adressen erstellt?', 2, '[{"text": "Ja", "correct": true, "because": "Mit globalem Präfix"}, {"text": "Nein", "correct": false, "because": "Abhängig von Router"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher NDP-Fehler zeigt einen Konflikt an?', 4, '[{"text": "Duplicate Address Detected", "correct": true, "because": "DAD schlägt fehl"}, {"text": "Router Advertisement fehlt", "correct": false, "because": "Anderer Fehler"}, {"text": "Echo Reply ausbleibt", "correct": false, "because": "Ping-spezifisch"}]');
